INSERT INTO "Announcement" ("id", "orgId", "authorMembershipId", "title", "body", "pinned", "createdAt", "updatedAt") VALUES ('cmwlz7mf700kwq4bhbaxg4ih8', 'cmwlz7m5w000gq4bhp5wkvv8e', 'cmwlz7m69001cq4bhxcedd31u', 'New leave policy effective this month', 'Annual leave balance now accrues monthly. Casual leave requests need 48h notice except emergencies. Full policy in Documents → Policies.', 0, '2026-11-11T10:26:16.771Z', '2026-11-18T10:26:16.771Z');
